{
  "critique": [
    {
      "design": "r1A",
      "good": "错误码和错误信息完整并列，首屏也能看到整个“含义”列；三列的对应关系容易沿行追踪。解决办法比 r1C 宽，表格高度有所控制。",
      "problems": "“含义”列仍很局促，access_token 被拆开，中文说明也形成许多短行。解决办法需要横向滚动才能阅读，较高的行使识别信息下方留下大片空白。",
      "cause": "前两列合计 245px，114px 的“含义”列恰好用完首屏余宽，但其 93px 内容宽度小于最长标识符所需的 95px；240px 的解决办法列仍需较多换行。"
    },
    {
      "design": "r1B",
      "good": "四列均未发生单词中途拆分；较宽的“含义”和“解决办法”让说明更连贯，行高比另外两版低，同一行的内容更容易比较。",
      "problems": "首屏只能看到“含义”的一部分，句子在视口边缘被截断，读者需要横向移动才能完整判断故障；解决办法距离首屏更远。",
      "cause": "前两列占 245px，而“含义”列为 140px，前三列合计 385px，超出 360px 视口约 25px；260px 的解决办法列进一步增加总宽。"
    },
    {
      "design": "r1C",
      "good": "错误码、错误信息和完整的“含义”列都在首屏，横向滚动距离是三版中最短的。",
      "problems": "access_token 被拆开；解决办法排成很窄的长段落，导致各行特别高，识别列出现大量空白，纵向查找和保持同行对应都更费力。",
      "cause": "114px 的“含义”列比最长标识符的最低需求窄约 2px；180px 的解决办法列只有 159px 内容宽度，迫使长步骤大量换行。"
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "首屏优先",
      "widths": [70, 175, 116, 260],
      "change": "将“含义”加宽至 116px，按内容测量刚好容纳最长标识符；前三列仅比视口宽约 1px。解决办法沿用 r1B 的 260px，检验能否兼顾首屏判断与较合理的行高。"
    },
    {
      "name": "均衡阅读",
      "widths": [70, 175, 130, 280],
      "change": "在保留两列识别信息完整的基础上，给“含义”和解决办法更多宽度，减少短行与纵向空白；前三列超出视口约 15px，接受少量横向移动。"
    },
    {
      "name": "步骤优先",
      "widths": [70, 175, 140, 320],
      "change": "以 r1B 为基础加宽解决办法，探索更短的行高和更连贯的步骤阅读；代价是需要更长的横向滚动，且首屏仍看不全“含义”。"
    }
  ]
}
